import type { Readable } from 'node:stream';

export const STORAGE = Symbol('STORAGE');

export interface PutObjectInput {
  key: string;
  body: Buffer | Readable;
  contentType: string;
  contentLength?: number;
}

/**
 * Object storage used for attachments. Keys are generated by the app (never
 * user file names). Downloads go through short-lived URLs created only after
 * the caller's permissions were checked.
 */
export interface StorageProvider {
  readonly driver: 's3' | 'oci';
  putObject(input: PutObjectInput): Promise<void>;
  getObject(key: string): Promise<Readable>;
  deleteObject(key: string): Promise<void>;
  /** Signed, time-limited download URL (max 300 s), served as an attachment. */
  createDownloadUrl(key: string, ttlSeconds: number, downloadName: string): Promise<string>;
  /** Readiness probe. */
  ping(): Promise<void>;
}

export const MAX_DOWNLOAD_URL_TTL = 300;

export function assertSafeKey(key: string): void {
  if (!/^[a-z0-9][a-z0-9/_-]{0,255}$/.test(key) || key.includes('//') || key.includes('..')) {
    throw new Error('Invalid object key');
  }
}

/** RFC 6266 attachment header with an ASCII fallback and UTF-8 name. */
export function contentDisposition(name: string): string {
  const ascii =
    name
      .replace(/[^\x20-\x7e]/g, '_')
      .replace(/["\\]/g, '_')
      .slice(0, 150) || 'download';
  return `attachment; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(name.slice(0, 150))}`;
}
